verify:
  if: ${{ always() }}
  needs: [prepare-postgres, contracts, auth-integration, browser, native-no-store, native-no-store-fixed, user-assets-fixed]
  runs-on: ubuntu-24.04
  timeout-minutes: 20
  steps:
    - name: Require every contract and browser suite
      env:
        POSTGRES_RESULT: ${{ needs.prepare-postgres.result }}
        CONTRACT_RESULT: ${{ needs.contracts.result }}
        AUTH_INTEGRATION_RESULT: ${{ needs.auth-integration.result }}
        BROWSER_RESULT: ${{ needs.browser.result }}
        NATIVE_STREAM_RESULT: ${{ needs.native-no-store.result }}
        NATIVE_STREAM_FIXED_RESULT: ${{ needs.native-no-store-fixed.result }}
        USER_ASSETS_FIXED_RESULT: ${{ needs.user-assets-fixed.result }}
      run: test "$POSTGRES_RESULT" = success && test "$CONTRACT_RESULT" = success && test "$AUTH_INTEGRATION_RESULT" = success && test "$BROWSER_RESULT" = success && test "$NATIVE_STREAM_RESULT" = success && test "$NATIVE_STREAM_FIXED_RESULT" = success && test "$USER_ASSETS_FIXED_RESULT" = success
